## The Corrected Code

*With a wave of fairy magic, I'll mend what mortals have broken!*

```go
package cache

import (
    "context"
    "sync"
    "sync/atomic"
    "time"
)

type CacheEntry struct {
    Value     interface{}
    ExpiresAt time.Time
    ready     chan struct{} // Signal when loading completes
    err       error         // Store load error for waiters
}

type LoadFunc func(ctx context.Context, key string) (interface{}, error)

type Cache struct {
    data   map[string]*CacheEntry
    mu     sync.RWMutex // RWMutex for read-heavy workloads
    ttl    time.Duration
    loader LoadFunc
    stats  Stats
}

type Stats struct {
    Hits       int64
    Misses     int64
    LoadErrors int64
}

func NewCache(ttl time.Duration, loader LoadFunc) *Cache {
    c := &Cache{
        data:   make(map[string]*CacheEntry),
        ttl:    ttl,
        loader: loader,
    }
    go c.cleanupLoop()
    return c
}

func (c *Cache) Get(ctx context.Context, key string) (interface{}, error) {
    // Try read lock first for cache hit
    c.mu.RLock()
    entry, ok := c.data[key]
    if ok && entry.ready != nil {
        select {
        case <-entry.ready:
            // Entry is ready, check if valid
            if entry.err == nil && time.Now().Before(entry.ExpiresAt) {
                c.mu.RUnlock()
                atomic.AddInt64(&c.stats.Hits, 1)
                return entry.Value, nil
            }
        default:
            // Still loading, wait for it
            c.mu.RUnlock()
            return c.waitForLoad(ctx, entry)
        }
    }
    c.mu.RUnlock()

    // Cache miss or expired - need write lock
    c.mu.Lock()

    // Double-check after acquiring write lock
    entry, ok = c.data[key]
    if ok && entry.ready != nil {
        select {
        case <-entry.ready:
            if entry.err == nil && time.Now().Before(entry.ExpiresAt) {
                c.mu.Unlock()
                atomic.AddInt64(&c.stats.Hits, 1)
                return entry.Value, nil
            }
            // Expired or errored, fall through to reload
        default:
            // Still loading
            c.mu.Unlock()
            return c.waitForLoad(ctx, entry)
        }
    }

    // Create loading entry with channel
    entry = &CacheEntry{
        ready: make(chan struct{}),
    }
    c.data[key] = entry
    c.mu.Unlock()

    atomic.AddInt64(&c.stats.Misses, 1)

    // Load value outside lock
    value, err := c.loader(ctx, key)

    c.mu.Lock()
    if err != nil {
        atomic.AddInt64(&c.stats.LoadErrors, 1)
        entry.err = err
        delete(c.data, key)
    } else {
        entry.Value = value
        entry.ExpiresAt = time.Now().Add(c.ttl)
        entry.err = nil
    }
    close(entry.ready) // Signal all waiters
    c.mu.Unlock()

    return value, err
}

func (c *Cache) waitForLoad(ctx context.Context, entry *CacheEntry) (interface{}, error) {
    select {
    case <-ctx.Done():
        return nil, ctx.Err()
    case <-entry.ready:
        if entry.err != nil {
            return nil, entry.err
        }
        return entry.Value, nil
    }
}

func (c *Cache) Set(key string, value interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()

    entry := &CacheEntry{
        Value:     value,
        ExpiresAt: time.Now().Add(c.ttl),
        ready:     make(chan struct{}),
    }
    close(entry.ready)
    c.data[key] = entry
}

func (c *Cache) Invalidate(key string) {
    c.mu.Lock()
    defer c.mu.Unlock()
    delete(c.data, key)
}

func (c *Cache) InvalidateAll() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data = make(map[string]*CacheEntry)
}

func (c *Cache) GetMulti(ctx context.Context, keys []string) map[string]interface{} {
    var wg sync.WaitGroup
    var mu sync.Mutex
    results := make(map[string]interface{})

    for _, key := range keys {
        wg.Add(1)
        go func(k string) {
            defer wg.Done()
            value, err := c.Get(ctx, k)
            if err == nil {
                mu.Lock()
                results[k] = value
                mu.Unlock()
            }
        }(key)
    }
    wg.Wait()
    return results
}

func (c *Cache) cleanupLoop() {
    ticker := time.NewTicker(time.Minute)
    defer ticker.Stop()
    for range ticker.C {
        c.cleanup()
    }
}

func (c *Cache) cleanup() {
    c.mu.Lock()
    defer c.mu.Unlock()

    now := time.Now()
    for key, entry := range c.data {
        select {
        case <-entry.ready:
            if now.After(entry.ExpiresAt) {
                delete(c.data, key)
            }
        default:
            // Still loading, don't delete
        }
    }
}

func (c *Cache) Size() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return len(c.data)
}

func (c *Cache) GetStats() Stats {
    return Stats{
        Hits:       atomic.LoadInt64(&c.stats.Hits),
        Misses:     atomic.LoadInt64(&c.stats.Misses),
        LoadErrors: atomic.LoadInt64(&c.stats.LoadErrors),
    }
}

func (c *Cache) Refresh(ctx context.Context, key string) error {
    value, err := c.loader(ctx, key)
    if err != nil {
        return err
    }
    c.Set(key, value)
    return nil
}

func (c *Cache) LoadOrStore(ctx context.Context, key string, loader LoadFunc) (interface{}, error) {
    // Use the same pattern as Get but with custom loader
    originalLoader := c.loader
    c.loader = loader
    defer func() { c.loader = originalLoader }()
    return c.Get(ctx, key)
}
```

---

## Key Fixes Summary

| Issue | Fix |
|-------|-----|
| Unsynchronized map access | `RWMutex` everywhere |
| Stats races | `atomic.AddInt64` / `atomic.LoadInt64` |
| Cache stampede | Channel-based signaling, waiters block properly |
| GetMulti races | `sync.WaitGroup` + local mutex for results |
| cleaning flag race | Removed - mutex handles it |
| Spin-polling | Replaced with channel select |

*If we shadows have offended, think but this and all is mended—proper locks and channels true, make your cache work right for you!*
